## 5. Least privilege for the pipeline

The CI key only ever deploys cart-api, from the CI runners. Rewrite its policy to exactly that, add a guardrail, close the invoices bucket, and replay the audit trail until the attacker gets nothing and the deploys still work.

```tool cloudiam
{"pol": "{
 "account": "monsoon-prod",
 "identities": [
  {
   "name": "ci-deployer",
   "type": "user",
   "note": "used by the CI runners (egress 203.0.113.20) to deploy cart-api",
   "policies": [
    {
     "name": "deploy-cart-api-only",
     "statements": [
      {
       "effect": "Allow",
       "actions": [
        "DeployService"
       ],
       "resources": [
        "service/cart-api"
       ],
       "conditions": {
        "source_ip": [
         "203.0.113.20/32"
        ]
       }
      }
     ]
    }
   ]
  },
  {
   "name": "ananya",
   "type": "user",
   "note": "Ananya Rao, CTO",
   "policies": [
    {
     "name": "admin",
     "statements": [
      {
       "effect": "Allow",
       "actions": [
        "*"
       ],
       "resources": [
        "*"
       ]
      }
     ]
    }
   ]
  }
 ],
 "org_guardrails": [
  {
   "name": "keys-and-new-regions-need-mfa",
   "statements": [
    {
     "effect": "Deny",
     "actions": [
      "CreateAccessKey",
      "RunInstances"
     ],
     "resources": [
      "*"
     ],
     "conditions": {
      "mfa": false
     }
    }
   ]
  }
 ],
 "buckets": [
  {
   "name": "monsoon-invoices",
   "public_read": false,
   "encrypted": true,
   "versioning": true,
   "access_logging": true,
   "note": "customer invoices, meant to be private"
  },
  {
   "name": "monsoon-assets",
   "public_read": true,
   "encrypted": true,
   "versioning": true,
   "access_logging": true,
   "note": "product images, meant to be public"
  }
 ]
}
", "n": 0, "broken": 0, "files": ["cloud/policies.json"], "blank": ["pol"]}
```

| Before | After |
|---|---|
| ci-deployer: AdministratorAccess (`*` on `*`) | ci-deployer: `DeployService` on `service/cart-api`, only from 203.0.113.20 |
| no guardrails | Deny `CreateAccessKey` and `RunInstances` without MFA |
| monsoon-invoices public, no versioning, no logging | private, versioning on, access logging on |

- [ ] 0 attacker actions allowed, 0 deploys broken
- [ ] Bucket check: only monsoon-assets is public
- [ ] Better still: what replaces a long-lived key in CI? (short-lived credentials the CI asks for at deploy time)

